package net.civeira.phylax.feature.identity.userpurposeconsent.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.userpurposeconsent.domain.UserPurposeConsent;
import net.civeira.phylax.feature.identity.userpurposeconsent.domain.valueobject.IpAddressVO;

class IpAddressValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of ip address of user purpose consent")
  void test_ip_address_value_holder_assign_plain_value() {
    Object holder = new Object();
    IpAddressValueHolder<Object> value = new IpAddressValueHolder<>(holder);
    Assertions.assertSame(holder, value.ipAddress("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getIpAddressValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getIpAddress().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.ipAddressNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getIpAddressValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getIpAddress().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of ip address of user purpose consent")
  void test_ip_address_value_holder_assign_value_object() {
    Object holder = new Object();
    IpAddressValueHolder<Object> value = new IpAddressValueHolder<>(holder);
    IpAddressVO vo = IpAddressVO.from("one");
    Assertions.assertFalse(value.getIpAddressValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.ipAddress(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getIpAddressValue().orElseThrow());
    Assertions.assertSame(holder, value.ipAddress(Optional.empty()));
    Assertions.assertFalse(value.getIpAddressValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.ipAddress(Optional.of(vo)));
    Assertions.assertSame(vo, value.getIpAddressValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of ip address of user purpose consent against the original")
  void test_ip_address_value_holder_read() {
    Object holder = new Object();
    IpAddressValueHolder<Object> value = new IpAddressValueHolder<>(holder);
    IpAddressVO vo = IpAddressVO.from("one");
    IpAddressVO other = IpAddressVO.from("one");
    UserPurposeConsent original = Mockito.mock(UserPurposeConsent.class);
    Mockito.when(original.getIpAddressValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readIpAddress(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readIpAddress(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.ipAddress(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readIpAddress(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readIpAddress(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of ip address of user purpose consent")
  void test_ip_address_value_holder_unset() {
    Object holder = new Object();
    IpAddressValueHolder<Object> value = new IpAddressValueHolder<>(holder);
    IpAddressVO vo = IpAddressVO.from("one");
    value.ipAddress(vo);
    Assertions.assertSame(holder, value.unsetIpAddressIfMatches("ipAddress_other"));
    Assertions.assertTrue(value.getIpAddressValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetIpAddressIfMatches("ipAddress"));
    Assertions.assertFalse(value.getIpAddressValue().isPresent(),
        "The field name must clear the value");
    value.ipAddress(vo);
    Assertions.assertSame(holder, value.unsetIpAddress());
    Assertions.assertFalse(value.getIpAddressValue().isPresent(), "Unset must clear the value");
  }
}
